// The Gironde 2026 pack, and the promises its header makes about it.
//
// Two kinds of test live here, and the second kind is the point. The first is
// the ordinary sort: pure helpers, ladders, projections. The second reads the
// SHIPPED FILES and asserts they still say what the module header claims they
// say — that the drawn hectares track Copernicus's published ones, that holes
// survived the build, that no coordinate wandered outside the box. A pack is
// generated by a script nobody runs twice a year; without these, a silent
// regression in `build-gironde-megafire-2026.mjs` would ship a wrong fire and
// nothing would go red.
import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

import {
  MEGAFIRE_BBOX,
  MEGAFIRE_CREDITS,
  MEGAFIRE_FRP_LADDER,
  MEGAFIRE_MIN_HOLE_HA,
  MEGAFIRE_MIN_RING_HA,
  MEGAFIRE_SCHEMA,
  MEGAFIRE_STEPS,
  MEGAFIRE_STEP_COLORS,
  MEGAFIRE_WINDOW_END,
  MEGAFIRE_WINDOW_START,
  megafireFrpLevel,
  megafirePolygonAreaM2,
  megafireRingAreaM2,
  megafireStepAt,
  megafireToDegrees,
  megafireToMetres,
} from './megafirePack.js';

const HERE = path.dirname(fileURLToPath(import.meta.url));
const PACK = path.join(HERE, 'local_data', 'gironde_megafire_2026');
const event = JSON.parse(fs.readFileSync(path.join(PACK, 'event.json'), 'utf8'));
const hotspots = JSON.parse(fs.readFileSync(path.join(PACK, 'hotspots.json'), 'utf8'));

// --- Pure helpers -----------------------------------------------------------

test('the FRP ladder is geometric and ordered', () => {
  const mins = MEGAFIRE_FRP_LADDER.map((rung) => rung.min);
  assert.deepEqual(mins, [...mins].sort((a, b) => a - b), 'thresholds must climb');
  assert.equal(mins[0], 0, 'the first rung has to catch everything');
  for (let i = 2; i < mins.length; i += 1) {
    assert.ok(mins[i] / mins[i - 1] >= 2, `rung ${i} is not a geometric step up`);
  }
});

test('a detection lands on the rung its power says', () => {
  assert.equal(megafireFrpLevel(0), 0);
  assert.equal(megafireFrpLevel(9.9), 0);
  assert.equal(megafireFrpLevel(10), 1);
  assert.equal(megafireFrpLevel(49.9), 1);
  assert.equal(megafireFrpLevel(50), 2);
  assert.equal(megafireFrpLevel(1573.57), 3, 'the pack’s own maximum is on the top rung');
  assert.equal(megafireFrpLevel(NaN), 0, 'a missing power is the bottom rung, never a throw');
  assert.equal(megafireFrpLevel(undefined), 0);
});

test('the projection round-trips to within the shipped precision', () => {
  for (const [lon, lat] of [[-1.03, 44.89], [-1.45, 44.30], [-0.55, 45.15]]) {
    const [x, y] = megafireToMetres(lon, lat);
    const [lon2, lat2] = megafireToDegrees(x, y);
    assert.ok(Math.abs(lon2 - lon) < 1e-5, `lon ${lon} → ${lon2}`);
    assert.ok(Math.abs(lat2 - lat) < 1e-5, `lat ${lat} → ${lat2}`);
  }
});

test('a ring’s area is its shoelace, and holes are subtracted', () => {
  const square = [0, 0, 1000, 0, 1000, 1000, 0, 1000];
  assert.equal(megafireRingAreaM2(square), 1e6);
  // Wound the other way, the area is the same: the sign is not information here.
  assert.equal(megafireRingAreaM2([0, 0, 0, 1000, 1000, 1000, 1000, 0]), 1e6);
  const hole = [250, 250, 750, 250, 750, 750, 250, 750];
  assert.equal(megafirePolygonAreaM2([square, hole]), 1e6 - 25e4);
  assert.equal(megafireRingAreaM2([0, 0, 1, 1]), 0, 'two points bound nothing');
  assert.equal(megafirePolygonAreaM2([]), 0);
});

test('a polygon can never report a negative area', () => {
  const small = [0, 0, 10, 0, 10, 10, 0, 10];
  const huge = [-1000, -1000, 1000, -1000, 1000, 1000, -1000, 1000];
  assert.equal(megafirePolygonAreaM2([small, huge]), 0, 'a hole bigger than its ring floors at zero');
});

test('the step at an instant is a lookup, never an interpolation', () => {
  const before = Date.parse('2026-07-23T00:00:00Z');
  const first = Date.parse(MEGAFIRE_STEPS[0].acq);
  const between = Date.parse('2026-07-25T00:00:00Z');
  assert.equal(megafireStepAt(before), null, 'before the first frame there is no perimeter');
  assert.equal(megafireStepAt(first), 0, 'a frame is true from its own acquisition instant');
  assert.equal(megafireStepAt(first - 1), null);
  assert.equal(megafireStepAt(between), 0, 'the gap holds the LAST frame, it does not tween');
  assert.equal(megafireStepAt(Date.parse('2030-01-01T00:00:00Z')), MEGAFIRE_STEPS.length - 1);
  assert.equal(megafireStepAt(NaN), null);
});

// --- The shipped pack -------------------------------------------------------

test('the pack is the schema this module was written against', () => {
  assert.equal(event.schema, MEGAFIRE_SCHEMA);
  assert.equal(hotspots.schema, MEGAFIRE_SCHEMA);
  assert.equal(event.window.start, MEGAFIRE_WINDOW_START);
  assert.equal(event.window.end, MEGAFIRE_WINDOW_END);
  assert.equal(hotspots.epoch, MEGAFIRE_WINDOW_START);
});

test('every declared step shipped, in acquisition order, with its own figures', () => {
  assert.equal(event.steps.length, MEGAFIRE_STEPS.length);
  let previous = 0;
  event.steps.forEach((shipped, index) => {
    const declared = MEGAFIRE_STEPS[index];
    assert.equal(shipped.id, declared.id);
    assert.equal(shipped.acq, declared.acq, `${declared.id} acquisition drifted`);
    assert.equal(shipped.burntHa, declared.burntHa, `${declared.id} hectares drifted`);
    const acq = Date.parse(shipped.acq);
    assert.ok(acq > previous, 'steps must be in acquisition order');
    previous = acq;
    assert.ok(shipped.rings.length > 0, `${declared.id} shipped no geometry`);
  });
});

test('the acquisition times are inside the window they claim to reconstruct', () => {
  const start = Date.parse(MEGAFIRE_WINDOW_START);
  const end = Date.parse(MEGAFIRE_WINDOW_END);
  for (const step of MEGAFIRE_STEPS) {
    const acq = Date.parse(step.acq);
    assert.ok(acq >= start && acq <= end, `${step.id} sits outside the window`);
  }
});

test('the raw geometry reproduces the publisher’s hectares within 0.5 %', () => {
  // The claim in the module header, kept honest. `measuredHa` is the shoelace
  // area of the UNSIMPLIFIED rings; a build that started reading outer rings
  // only came out 10-13 % high, which is the failure this guards.
  for (const step of event.steps) {
    const drift = step.measuredHa / step.burntHa - 1;
    assert.ok(Math.abs(drift) < 0.005,
      `${step.id}: ${step.measuredHa} ha measured vs ${step.burntHa} published (${(drift * 100).toFixed(2)} %)`);
  }
});

test('simplification moved every perimeter by less than 3 %', () => {
  for (const step of event.steps) {
    const drift = step.drawnHa / step.measuredHa - 1;
    assert.ok(Math.abs(drift) < 0.03,
      `${step.id}: drawn ${step.drawnHa} ha vs measured ${step.measuredHa} ha`);
  }
});

test('holes survived the build, and they are worth keeping', () => {
  const withHoles = event.steps.filter((step) => step.rings.some((rings) => rings.length > 1));
  assert.ok(withHoles.length >= 4, 'at least four of the five products carve out unburnt ground');
  // Quantified rather than asserted loosely: on the 29 July product the holes
  // are thousands of hectares, not rounding.
  const monit02 = event.steps.find((step) => step.id === 'del-monit02');
  let outer = 0;
  let net = 0;
  for (const rings of monit02.rings) {
    const flat = rings.map(toFlatMetres);
    outer += megafireRingAreaM2(flat[0]);
    net += megafirePolygonAreaM2(flat);
  }
  const carved = (outer - net) / 1e4;
  assert.ok(carved > 3000, `holes carve only ${carved.toFixed(0)} ha out of the 29 July perimeter`);
});

test('every shipped ring is closed enough to draw, and inside the box', () => {
  const rings = [];
  for (const step of event.steps) for (const polygon of step.rings) rings.push(...polygon);
  for (const polygon of event.effis.main.rings) rings.push(...polygon);
  assert.ok(rings.length > 0);
  for (const flat of rings) {
    assert.equal(flat.length % 2, 0, 'a ring is pairs of numbers');
    assert.ok(flat.length >= 8, 'a ring under four points bounds nothing');
    for (let i = 0; i < flat.length; i += 2) {
      const lon = flat[i];
      const lat = flat[i + 1];
      assert.ok(Number.isFinite(lon) && Number.isFinite(lat), 'a coordinate is not a number');
      assert.ok(lon >= MEGAFIRE_BBOX.west && lon <= MEGAFIRE_BBOX.east, `lon ${lon} left the box`);
      assert.ok(lat >= MEGAFIRE_BBOX.south && lat <= MEGAFIRE_BBOX.north, `lat ${lat} left the box`);
    }
  }
});

test('no shipped ring is under the threshold the build promises to drop', () => {
  for (const step of event.steps) {
    for (const polygon of step.rings) {
      const flat = polygon.map(toFlatMetres);
      assert.ok(megafireRingAreaM2(flat[0]) >= MEGAFIRE_MIN_RING_HA * 1e4 * 0.9,
        `${step.id} shipped an outer ring under ${MEGAFIRE_MIN_RING_HA} ha`);
      for (let i = 1; i < flat.length; i += 1) {
        assert.ok(megafireRingAreaM2(flat[i]) >= MEGAFIRE_MIN_HOLE_HA * 1e4 * 0.9,
          `${step.id} shipped a hole under ${MEGAFIRE_MIN_HOLE_HA} ha`);
      }
    }
  }
});

test('the fire that was photographed only ever grows', () => {
  // Not a tautology: a delineation is cumulative, so a product that shrank
  // would mean the build paired a perimeter with the wrong date.
  const areas = event.steps.map((step) => step.burntHa);
  for (let i = 1; i < areas.length - 1; i += 1) {
    assert.ok(areas[i] > areas[i - 1], `step ${i} lost ground`);
  }
  // The exception, and it is real: the last GRADING product remeasures the same
  // fire off a later image and lands 276 ha BELOW the delineation before it.
  // That is Copernicus disagreeing with itself by 0.9 %, not a build error.
  const last = areas[areas.length - 1];
  const previous = areas[areas.length - 2];
  assert.ok(last < previous, 'the closing grading is expected to sit just under MONIT02');
  assert.ok((previous - last) / previous < 0.02, 'but only just — 2 % is the tolerance');
});

test('EFFIS closes bigger than Copernicus, and says so with a date', () => {
  const effis = event.effis.main;
  const last = event.steps[event.steps.length - 1];
  assert.ok(effis.areaHa > last.burntHa,
    'EFFIS runs on after the mappers stop; a smaller EFFIS means the wrong polygon was picked');
  assert.equal(effis.commune, 'Porge');
  assert.ok(Date.parse(effis.firstDetection) <= Date.parse(MEGAFIRE_STEPS[0].acq));
  assert.ok(effis.rings.length > 0);
  assert.ok(event.effis.others.length > 0, 'the flare-ups around the main fire are part of the record');
});

test('the hotspot table is what the layer expects to index', () => {
  assert.deepEqual(hotspots.columns, ['lon', 'lat', 'minutes', 'frp', 'confidence', 'source']);
  assert.ok(hotspots.rows.length > 8000, `only ${hotspots.rows.length} detections shipped`);
  const windowMinutes = (Date.parse(MEGAFIRE_WINDOW_END) - Date.parse(MEGAFIRE_WINDOW_START)) / 60000;
  let previous = -Infinity;
  for (const row of hotspots.rows) {
    assert.equal(row.length, hotspots.columns.length);
    const [lon, lat, minutes, frp, , source] = row;
    assert.ok(lon >= MEGAFIRE_BBOX.west && lon <= MEGAFIRE_BBOX.east);
    assert.ok(lat >= MEGAFIRE_BBOX.south && lat <= MEGAFIRE_BBOX.north);
    assert.ok(minutes >= 0 && minutes <= windowMinutes, `minute ${minutes} is outside the window`);
    assert.ok(minutes >= previous, 'detections must ship in time order');
    previous = minutes;
    assert.ok(Number.isFinite(frp) && frp >= 0);
    assert.ok(source >= 0 && source < hotspots.sources.length, 'a detection names a satellite that shipped');
  }
});

test('all four satellites contributed, and the peak day is the one the record names', () => {
  const bySource = new Array(hotspots.sources.length).fill(0);
  const byDay = new Map();
  const epoch = Date.parse(hotspots.epoch);
  for (const row of hotspots.rows) {
    bySource[row[5]] += 1;
    const day = new Date(epoch + row[2] * 60000).toISOString().slice(0, 10);
    byDay.set(day, (byDay.get(day) || 0) + 1);
  }
  for (let i = 0; i < bySource.length; i += 1) {
    assert.ok(bySource[i] > 0, `${hotspots.sources[i]} contributed nothing — a source silently dropped`);
  }
  const peak = [...byDay.entries()].sort((a, b) => b[1] - a[1])[0];
  assert.equal(peak[0], '2026-07-24', 'the run of 24 July is the busiest day in the record');
});

test('there is one colour per step, and one credit per publisher in the pack', () => {
  assert.ok(MEGAFIRE_STEP_COLORS.length >= MEGAFIRE_STEPS.length);
  const unique = new Set(MEGAFIRE_STEP_COLORS.slice(0, MEGAFIRE_STEPS.length));
  assert.equal(unique.size, MEGAFIRE_STEPS.length, 'two steps sharing a colour cannot be told apart');
  const sources = MEGAFIRE_CREDITS.map((credit) => credit.source);
  assert.deepEqual(sources, ['Copernicus EMS Rapid Mapping', 'EFFIS', 'NASA FIRMS']);
  for (const credit of event.credits) {
    assert.match(credit.credit, /\S/);
    assert.match(credit.url, /^https:\/\//);
  }
});

/**
 * A shipped degree ring → flat metres, so the area helpers can read it.
 * @param {number[]} flat - `[lon, lat, ...]`.
 * @returns {number[]} `[x, y, ...]`.
 */
function toFlatMetres(flat) {
  const out = new Array(flat.length);
  for (let i = 0; i < flat.length; i += 2) {
    const [x, y] = megafireToMetres(flat[i], flat[i + 1]);
    out[i] = x;
    out[i + 1] = y;
  }
  return out;
}
